revoke all on function public.cardforge_catalog_consumer_inspectable(jsonb,text,integer) from public,anon,authenticated;
revoke all on function public.cardforge_catalog_trash_inventory_details(uuid) from public,anon,authenticated;
grant execute on function public.cardforge_catalog_consumer_inspectable(jsonb,text,integer) to service_role;
grant execute on function public.cardforge_catalog_trash_inventory_details(uuid) to service_role;
